feed:
  {{ site_name }} — {{ chain.label }} incidents
  Outages, reorgs, forks and stalls, as observed from one vantage point.
  tag:{{ tag_host }},2026:{{ chain.value }}/incidents


  {{ updated | rfc3339 }}
