{% for e in events %}

    tag:{{ tag_host }},2026:{{ chain.value }}/event/{{ e.id }}
    {% if e.kind.value != 'reorg' and not e.ongoing %}Resolved: {% endif %}{{ e.kind | event_label }} — {{ e.subject }}{% if e.occurrences > 1 %} — {{ e.occurrences }} times in 24 h{% endif %}

    {{ e.started_at | rfc3339 }}
    {{ e.updated_at | rfc3339 }}


    {% if e.occurrences > 1 %}{{ e.occurrences }} {{ e.kind | event_plural }} in 24 h, the first {{ e.started_at | when }}{% if e.kind | event_active %}, {{ e.active_total_s | duration }} {{ e.kind | event_active }} in total{% endif %}. Latest: {% endif %}{% if e.detail %}{{ e.detail }}. {% endif %}Started {{ e.latest_start | when }}{% if e.kind.value == 'reorg' %}.{% elif e.ongoing %}, ongoing.{% else %}, ended {{ e.ended_at | when }} after {{ e.last_duration_s | duration }}.{% endif %}

{% endfor %}
